mapper.select:
SELECT  FROM logan_error

ORDER BY occurred_at DESC
 LIMIT #{q.offset}, #{q.limit}
 LIMIT #{q.limit}

SELECT  FROM logan_error
WHERE app_id = #{appId} AND device_id = #{deviceId}
  AND occurred_at BETWEEN #{beginTime} AND #{endTime}
ORDER BY occurred_at DESC LIMIT #{limit}

SELECT COUNT(*) AS events, COUNT(DISTINCT device_id) AS devices,
       COUNT(DISTINCT fingerprint) AS issues
FROM logan_error

    app_id = #{appId}
    AND occurred_at BETWEEN #{beginTime} AND #{endTime}
     AND platform = #{platform}
     AND app_version = #{appVersion}

SELECT name AS name, COUNT(*) AS events, COUNT(DISTINCT device_id) AS devices,
       COUNT(DISTINCT fingerprint) AS issues, MAX(occurred_at) AS lastTime
FROM logan_error

    app_id = #{appId}
    AND occurred_at BETWEEN #{beginTime} AND #{endTime}
    AND name IS NOT NULL AND name != ''
     AND platform = #{platform}
     AND app_version = #{appVersion}

GROUP BY name
ORDER BY events DESC
LIMIT #{limit}

SELECT  FROM logan_error_issue

    app_id = #{q.appId}
     AND status_flag = #{q.statusFlag}
     AND kind = #{q.kind}
     AND platform = #{q.platform}
     AND assignee = #{q.assignee}

        AND (name LIKE CONCAT('%',#{q.keyword},'%') OR title LIKE CONCAT('%',#{q.keyword},'%')
             OR fingerprint LIKE CONCAT('%',#{q.keyword},'%'))


ORDER BY last_seen DESC LIMIT #{q.limit}

